import { calcTotal } from "../src/pricing.ts";

test("calcTotal applies no discount under 10 units", () => {
  assert.equal(calcTotal([{ sku: "a", price: 2, qty: 5 }, { sku: "b", price: 3, qty: 4 }]), 22);
});

test("calcTotal takes 10% off at 10 or more units", () => {
  assert.equal(calcTotal([{ sku: "a", price: 2, qty: 6 }, { sku: "b", price: 4, qty: 4 }]), 25.2);
});

